// The PIAX range: one source for every section that shows pads, packs or prices.
// Values live in productCatalog.json (the fixed PIAX range); this module adds the box photos
// and helpers. Box photos are generated by scripts/generate-pack-images.py from the same catalogue.
import catalog from './productCatalog.json'

const boxPhotos = import.meta.glob('../assets/products/piax-*.webp', { eager: true, import: 'default' })
const boxPhoto = (slug) => boxPhotos[`../assets/products/piax-${slug}.webp`]

export const colours = catalog.colours

// Pads, in size order. Each pad is sold in one box with a fixed pad count and price; `packs` holds that box
// (a list, so cards and the cart treat every pack the same way). `mrp` is struck through beside the price, with the % OFF.
export const pads = catalog.pads.map(({ box, ...pad }) => ({
  ...pad,
  packs: [{
    id: `piax-${pad.id}-${box.count}`,
    format: 'box',
    formatName: 'Box',
    label: `${pad.name.replace('PIAX ', '')} ${box.count}`,
    count: box.count,
    mrp: box.mrp ?? box.price,
    price: box.price,
    image: boxPhoto(`${pad.id}-${box.count}`),
  }],
}))

export const padById = Object.fromEntries(pads.map((pad) => [pad.id, pad]))

// The box a pad is sold in.
export const standardPack = (pad) => pad.packs[0]

// The PIAX Cycle Pack (called `combo` in code): exactly `count` pads in any mix of sizes, at one flat price,
// with its own product page at `path`. `presets` are ready-made mixes;
// the first is the default suggestion.
export const combo = {
  ...catalog.combo,
  mrp: catalog.combo.mrp ?? catalog.combo.price,
  image: boxPhoto(`${catalog.combo.id}-${catalog.combo.count}`),
  path: `/products/${catalog.combo.slug}`,
}

export const mixCount = (mix) => Object.values(mix).reduce((sum, count) => sum + count, 0)

// A mix in a link (`/products/cycle-pack?mix=3.4.3.2`, counts in size order), so another page can open the Cycle Pack
// with a mix already chosen. `parseMix` returns null for anything that is not a full box.
export const mixParam = (mix) => pads.map((pad) => mix[pad.id] ?? 0).join('.')
export const parseMix = (value) => {
  const counts = String(value ?? '').split('.').map(Number)
  if (counts.length !== pads.length || counts.some((n) => !Number.isInteger(n) || n < 0)) return null
  const mix = Object.fromEntries(pads.map((pad, index) => [pad.id, counts[index]]))
  return mixCount(mix) === catalog.combo.count ? mix : null
}

// Cart entry for a Cycle Pack. The id is built from the mix, so two identical combos stack and different ones don't.
export const comboItem = (mix) => {
  const chosen = pads.filter((pad) => mix[pad.id] > 0)
  return {
    id: `piax-${combo.id}-${chosen.map((pad) => `${pad.id}${mix[pad.id]}`).join('-')}`,
    name: combo.name,
    subtitle: chosen.map((pad) => `${mix[pad.id]} × ${pad.size}`).join(' · '),
    price: combo.price, mrp: combo.mrp, boxCount: combo.count, image: combo.image,
    mix: { ...mix },
  }
}

// Product features with their validation status (validated | prohibited).
export const productFeatures = catalog.features

// Features cleared for the shop listing, shared by every pad.
export const sharedFeatures = productFeatures
  .filter((feature) => feature.status === 'validated' && feature.approvedFor.includes('product_listing') && feature.id !== 'length' && feature.id !== 'regular-pad')
  .map((feature) => feature.label)

export const directionsOfUse = catalog.directionsOfUse

export const discount = ({ mrp, price }) => (mrp > price ? Math.round((1 - price / mrp) * 100) : 0)
export const perPad = ({ price, count }) => (price / count).toFixed(2).replace(/\.00$/, '')

// Subscribe & save: a box of any pack or the Cycle Pack arrives every month for a chosen length (`terms`: 3 months,
// 6 months or 1 year). Longer subscriptions save more, and the longest (`best`) is the suggested choice.
export const subscription = catalog.subscription
export const termFor = (months) => subscription.terms.find((item) => item.months === months) ?? subscription.terms[0]
export const bestTerm = subscription.terms.find((item) => item.best) ?? subscription.terms[subscription.terms.length - 1]
export const maxSubscribeDiscount = Math.max(...subscription.terms.map((item) => item.discountPercent))
// Price of each monthly box on a subscription of `months`.
export const subscribePrice = (price, months) => Math.round(price * (1 - termFor(months).discountPercent / 100))

// Cart entry for a subscription to `item`: the price is per monthly box. A separate id per length, so a one-time box
// and a subscription to the same product stay separate cart lines.
export const subscriptionItem = (item, months) => ({
  ...item,
  id: `${item.id}-sub${months}`,
  subtitle: `${item.subtitle} · Subscribe & save, monthly for ${termFor(months).label}`,
  price: subscribePrice(item.price, months),
  subscription: { months, deliveries: termFor(months).deliveries, discountPercent: termFor(months).discountPercent },
})
